import { optionalString, plainObject, resourceRefLabel } from "../../engine/pull/context.js";
import { reportUnknownAttrs } from "../../engine/pull/attrs.js";
import { scopedLabelToBagKey, tfLabelToTsLabel } from "../../engine/tf/index.js";
import { fieldKeyFromTfValue } from "../field/from-tf.js";
import { RECORD_CREATE_FORM_RESOURCE_TYPE } from "./module.js";
const KNOWN_ATTRS = new Set(["app_id", "sections"]);
const KNOWN_SECTION_ATTRS = new Set([
    "name", "field_ids", "agent_id", "icon", "color", "display_order", "display_location",
    "side_nav_item", "hidden", "max_columns",
]);
/** Provider resource -> id-free normalized create-form authoring. */
export function recordCreateFormFromTf(block, owner, ctx) {
    if (block === undefined)
        return undefined;
    const where = `${RECORD_CREATE_FORM_RESOURCE_TYPE}.${block.label ?? "?"}`;
    reportUnknownAttrs(block.attrs, KNOWN_ATTRS, where, "recordCreateFormFromTf", ctx);
    if (resourceRefLabel(block.attrs["app_id"], owner.type) !== owner.label) {
        ctx.diagnostics.push(`${where}: app_id does not reference ${owner.type}.${owner.label}; skipped`);
        return undefined;
    }
    const rawSections = block.attrs["sections"];
    if (!Array.isArray(rawSections)) {
        ctx.diagnostics.push(`${where}: sections is not a list; skipped`);
        return undefined;
    }
    const sections = [];
    for (const [index, raw] of rawSections.entries()) {
        const section = sectionFromTf(raw, index, where, owner, ctx);
        if (section !== undefined)
            sections.push(section);
    }
    return { sections };
}
function sectionFromTf(raw, index, formWhere, owner, ctx) {
    const rec = plainObject(raw);
    const where = `${formWhere} section ${index}`;
    if (rec === undefined) {
        ctx.diagnostics.push(`${where}: unrecognized shape; dropped`);
        return undefined;
    }
    reportUnknownAttrs(rec, KNOWN_SECTION_ATTRS, where, "recordCreateFormFromTf", ctx);
    const fieldIds = rec["field_ids"];
    if (!Array.isArray(fieldIds)) {
        ctx.diagnostics.push(`${where}: field_ids is not a list; dropped`);
        return undefined;
    }
    const fields = [];
    for (const fieldId of fieldIds) {
        const key = fieldKeyFromTfValue(fieldId, tfLabelToTsLabel(owner.label), owner.ownerTfLabel, owner.scope, ctx);
        if (key === undefined)
            ctx.diagnostics.push(`${where}: a field_ids entry is not a known field reference; dropped`);
        else
            fields.push(key);
    }
    const agentLabel = resourceRefLabel(rec["agent_id"], "elementum_agent");
    if (rec["agent_id"] !== undefined && agentLabel === undefined) {
        ctx.diagnostics.push(`${where}: agent_id is not an elementum_agent resource reference; dropped`);
    }
    if (agentLabel !== undefined && owner.scope !== "app") {
        ctx.diagnostics.push(`${where}: agent-assisted sections are only supported on app-owned forms; agent dropped`);
    }
    return {
        name: optionalString(rec, "name", where, ctx) ?? "",
        fields,
        ...(agentLabel !== undefined && owner.scope === "app" && { agentKey: scopedLabelToBagKey(owner.ownerTfLabel, agentLabel, "app") }),
        ...(typeof rec["icon"] === "string" && { icon: rec["icon"] }),
        ...(typeof rec["color"] === "string" && { color: rec["color"] }),
        ...(typeof rec["display_order"] === "number" && { displayOrder: rec["display_order"] }),
        ...(typeof rec["display_location"] === "string" && { displayLocation: rec["display_location"] }),
        ...(typeof rec["side_nav_item"] === "boolean" && { sideNavItem: rec["side_nav_item"] }),
        ...(typeof rec["hidden"] === "boolean" && { hidden: rec["hidden"] }),
        ...(typeof rec["max_columns"] === "number" && { maxColumns: rec["max_columns"] }),
    };
}
